def copy_condition_services(apps, schema_editor):
    """Every existing version keeps the services that took a condition level
    when it was published, Exterior Only included (decision 0103). Published
    versions never change, so the rows are written here, below the model's
    lock. The new rule comes with the next version."""
    Service = apps.get_model("pricebook", "Service")
    PricebookVersion = apps.get_model("pricebook", "PricebookVersion")
    ConditionService = apps.get_model("pricebook", "ConditionService")
    services = list(Service.objects.filter(condition_applies=True))
    for version in PricebookVersion.objects.all():
        for service in services:
            ConditionService.objects.get_or_create(version=version, service=service)


def restore_condition_applies(apps, schema_editor):
    Service = apps.get_model("pricebook", "Service")
    ConditionService = apps.get_model("pricebook", "ConditionService")
    ids = set(ConditionService.objects.values_list("service_id", flat=True))
    Service.objects.filter(pk__in=ids).update(condition_applies=True)


